ell done.'=>'Tidak ada apa-apa di sini. Kerja bagus.','Period'=>'Periode','Last 7 days'=>'7 hari terakhir','Last 30 days'=>'30 hari terakhir','Last 90 days'=>'90 hari terakhir','Last 12 months'=>'12 bulan terakhir','%s%% answered by the assistant alone'=>'%s%% dijawab oleh asisten saja','Handed to a person'=>'Diserahkan kepada seseorang','median wait %s'=>'perkiraan waktu tunggu %s','Tickets opened'=>'Tiket dibuka','%d still open'=>'%d masih terbuka','median · average %s'=>'median · rata-rata %s','Time to solve'=>'Waktu penyelesaian','median · %d solved'=>'median · %d terselesaikan','Customer satisfaction'=>'Kepuasan pelanggan','%d ratings, average %s of 5'=>'%d penilaian, rata-rata %s dari 5','SLA first reply met'=>'Tanggapan pertama SLA terpenuhi','%1$d due, %2$d missed'=>'%1$d jatuh tempo, %2$d terlewat','Assistant answers rated'=>'Jawaban Asisten Dinilai','helpful / rated'=>'bermanfaat / dinilai','Chats and tickets per day'=>'Percakapan dan tiket per hari','%1$d chats, %2$d tickets'=>'%1$d obrolan, %2$d tiket','Tickets answered'=>'Tiket terjawab','Replies'=>'Balasan','Rating'=>'Peringkat','Top topics'=>'Topik teratas','Where tickets came from'=>'Asal tiket']];